CustomField.formula:
if (ispickval(Main_Client__r.Pronouns__c, "She/Her") || ispickval(Main_Client__r.Pronouns__c, "He/Him") || ispickval(Main_Client__r.Pronouns__c, "They/Them"),

Main_Client__r.FirstName & " " & Main_Client__r.LastName & " " & Main_Client__r.Suffix & " ("& text(Main_Client__r.Pronouns__c)&")",

if(ispickval(Main_Client__r.Pronouns__c, "Write-In/Other"), 

Main_Client__r.FirstName & " " & Main_Client__r.LastName & " " & Main_Client__r.Suffix & " (See Contact record for Pronoun preferences)",

Main_Client__r.FirstName & " " & Main_Client__r.LastName & " " & Main_Client__r.Suffix))
